using LittleLeo;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "IndigoRiteAction", menuName = "Data/Battle/Battle Actions/Cellarius/IndigoRite Action")]
public class IndigoRiteAction : BattleAction
{
	[Header("Purify Action")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private DefaultEffectAction indigoRiteAction;

	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[SerializeField]
	private Effect indigoRiteEffect;

	[SerializeField]
	private DefaultEffectAction indigoSoulAction;

	[SerializeField]
	private DrawAction drawAction;

	[SerializeField]
	private int drawAmount = 1;

	[SerializeField]
	private HexAction gainIndigoRiteDieAction;

	public PurifyAction PurifyAction => purifyAction;

	public DefaultEffectAction IndigoRiteEffectAction => indigoRiteAction;

	public int DrawAmount => drawAmount;

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		purifyAction.CastTargetAmount(target, purifyAmount, source);
		indigoRiteAction.CastTargetAmount(target, 1, source);
		Dice dice = null;
		dice = ((!(ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance is DiceInstance)) ? ReferenceSingleton<AssetsReference>.Instance.AllPlayerDicesList.GetDice("IndigoRiteDie") : (ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance as DiceInstance).OriginalDice);
		gainIndigoRiteDieAction.CastWithRuntimeDie(source, dice);
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.4f, delegate
		{
			IndigoRiteTriggerCheck();
		});
	}

	public void IndigoRiteTriggerCheck()
	{
		if (currentActiveUnits.EveryTargetHasIndigoRite(indigoRiteEffect))
		{
			indigoSoulAction.CastTargetAmount(playerGameObjectReference.value, 1, null);
			drawAction.CastAmount(drawAmount, null);
		}
	}
}
